import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Button from "../../ui/shadcn-button";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("flex flex-col items-start gap-2")],
    [
      h.div(
        [h.Class("flex flex-wrap items-center gap-2")],
        [
          Button.view<Message>({
            toView: (attributes) =>
              h.button(
                [
                  ...attributes.button,
                  h.Class(
                    `${Button.shadcnButtonBaseClassName} ${Button.shadcnButtonVariantClassName} ${Button.shadcnButtonExtraSmallSizeClassName}`
                  ),
                ],
                ["Extra Small"]
              ),
          }),
          Button.view<Message>({
            toView: (attributes) =>
              h.button(
                [
                  ...attributes.button,
                  h.Class(
                    `${Button.shadcnButtonBaseClassName} ${Button.shadcnButtonVariantClassName} ${Button.shadcnButtonSmallSizeClassName}`
                  ),
                ],
                ["Small"]
              ),
          }),
          Button.view<Message>({
            toView: (attributes) =>
              h.button(
                [...attributes.button, h.Class(Button.shadcnButtonClassName)],
                ["Default"]
              ),
          }),
          Button.view<Message>({
            toView: (attributes) =>
              h.button(
                [
                  ...attributes.button,
                  h.Class(
                    `${Button.shadcnButtonBaseClassName} ${Button.shadcnButtonVariantClassName} ${Button.shadcnButtonLargeSizeClassName}`
                  ),
                ],
                ["Large"]
              ),
          }),
        ]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Button Size example", () => {
  test("renders the origin size buttons as inert", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("button", { name: "Extra Small" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Small" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Default" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Large" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Default" })).not.toHaveHandler(
        "click"
      )
    );
  });
});
